  ['// Cargo.toml: [dependencies] has this crate at version 1\nuse ___::Error;\n#[derive(Debug, Error)]\nenum OrderError {\n    #[error("order is empty")]\n    Empty,\n}\n'] = '// Cargo.toml: [dependencies] 里有这个 crate，版本 1\nuse ___::Error;\n#[derive(Debug, Error)]\nenum OrderError {\n    #[error("order is empty")]\n    Empty,\n}\n',
