  ['// Grill and Wok in one Vec: each boxed as a trait object.\nlet crew: Vec<___> = vec![Box::new(Grill), Box::new(Wok)];\nfor c in &crew { println!("{}", c.greet()); }\n'] = '// Grill 和 Wok 放进一个 Vec：各自装箱成 trait 对象。\nlet crew: Vec<___> = vec![Box::new(Grill), Box::new(Wok)];\nfor c in &crew { println!("{}", c.greet()); }\n',
