  ["// b'a' is the byte 97. Subtracting it maps a..z onto 0..26.\n// An array index must be the pointer-sized unsigned type.\nlet mut count = [0i32; 26];\nfor c in \"muffin\".bytes() {\n    count[(c - b'a') as ___] += 1;\n}\n"] = "// b'a' 是字节 97。减掉它，a..z 就映射到 0..26。\n// 数组下标必须是指针大小的无符号类型。\nlet mut count = [0i32; 26];\nfor c in \"muffin\".bytes() {\n    count[(c - b'a') as ___] += 1;\n}\n",
  ['// both futures make progress on this task at once\nlet (a, b) = tokio::___!(fetch_eta(1), fetch_eta(2));\nprintln!("rider A {a} min, rider B {b} min");\n'] = '// 两个 future 在这个任务上同时推进\nlet (a, b) = tokio::___!(fetch_eta(1), fetch_eta(2));\nprintln!("rider A {a} min, rider B {b} min");\n',
  ["// calling this does nothing yet; it hands back a Future\n___ fn fetch_eta(order_id: u32) -> u32 {\n    tokio::time::sleep(Duration::from_millis(200)).await;\n    order_id % 10 + 5\n}\n"] = "// 调用它什么都还不会发生；它只交回一个 Future\n___ fn fetch_eta(order_id: u32) -> u32 {\n    tokio::time::sleep(Duration::from_millis(200)).await;\n    order_id % 10 + 5\n}\n",
  ["// go f() starts a ___\n// thousands of them are cheap\n"] = "// go f() 启动一个 ___\n// 开几千个也很便宜\n",
  ["// merge(l, r): both slices are already sorted\nlet (mut i, mut j, mut out) = (0, 0, Vec::new());\nwhile i < l.len() && j < r.len() {\n    if l[i] ___ r[j] { out.push(l[i]); i += 1; }\n    else { out.push(r[j]); j += 1; }\n}\nout.extend(&l[i..]); out.extend(&r[j..]);\n"] = "// merge(l, r)：两个切片都已经有序\nlet (mut i, mut j, mut out) = (0, 0, Vec::new());\nwhile i < l.len() && j < r.len() {\n    if l[i] ___ r[j] { out.push(l[i]); i += 1; }\n    else { out.push(r[j]); j += 1; }\n}\nout.extend(&l[i..]); out.extend(&r[j..]);\n",
  ['// position gives an Option; the till wants a Result.\nfn find(menu: &[&str], w: &str) -> Result<usize, String> {\n    menu.iter()\n        .position(|m| *m == w)\n        .___("not on the menu".to_string())\n}\n'] = '// position 给的是 Option；收银机要 Result。\nfn find(menu: &[&str], w: &str) -> Result<usize, String> {\n    menu.iter()\n        .position(|m| *m == w)\n        .___("not on the menu".to_string())\n}\n',
  ["// returns a JoinHandle; the task runs on the pool now\nlet handle = tokio::___(async { fetch_eta(3).await });\nprint_menu().await;\nlet eta = handle.await?;\n"] = "// 返回 JoinHandle；任务现在已在线程池上跑了\nlet handle = tokio::___(async { fetch_eta(3).await });\nprint_menu().await;\nlet eta = handle.await?;\n",
  ["// starts a line comment. /// is a doc comment that cargo doc turns into pages."] = "// 开始一条行注释。/// 是文档注释，cargo doc 会把它变成网页。",
  ['// the caller only learns: it is some Iterator of &str\nfn free_riders() -> ___ Iterator<Item = &\'static str> {\n    ["Wing", "Fai"].into_iter().filter(|r| *r != "Fai")\n}\n'] = '// 调用方只知道：这是某个产出 &str 的 Iterator\nfn free_riders() -> ___ Iterator<Item = &\'static str> {\n    ["Wing", "Fai"].into_iter().filter(|r| *r != "Fai")\n}\n',
  ['// the mall has five floors of pickup lockers\nfor floor in 1___5 {\n    println!("checking locker on floor {floor}");\n}\n// prints 1, 2, 3, 4, 5\n'] = '// 商场有五层取餐柜\nfor floor in 1___5 {\n    println!("checking locker on floor {floor}");\n}\n// 打印 1, 2, 3, 4, 5\n',
  ['// three characters, three bytes each in UTF-8\nlet district = "銅鑼灣";\nlet n = district.___();\nassert_eq!(n, 9);\n'] = '// 三个字符，UTF-8 里每个占三字节\nlet district = "銅鑼灣";\nlet n = district.___();\nassert_eq!(n, 9);\n',
  ["// two_sum: value -> index in a HashMap, one pass, O(n)\nlet mut seen = HashMap::new();\nfor (i, &x) in nums.iter().enumerate() {\n    let want = target - x;\n    if seen.___(&want) { return Some((seen[&want], i)); }\n    seen.insert(x, i);\n}\n"] = "// two_sum：HashMap 里存 值 -> 下标，一趟搞定，O(n)\nlet mut seen = HashMap::new();\nfor (i, &x) in nums.iter().enumerate() {\n    let want = target - x;\n    if seen.___(&want) { return Some((seen[&want], i)); }\n    seen.insert(x, i);\n}\n",
  ["// worker(id, rx): the let drops the lock guard at the\n// semicolon, so the job runs with the rail unlocked.\nloop {\n    let msg = rx.lock().unwrap().___();\n    let Ok(job) = msg else { break };  // Err: senders gone\n    job();\n}\n"] = "// worker(id, rx)：这个 let 在分号处就丢掉了锁 guard，\n// 所以任务运行时这条轨是没锁的。\nloop {\n    let msg = rx.lock().unwrap().___();\n    let Ok(job) = msg else { break };  // Err：发送者都没了\n    job();\n}\n",
  ["//go:embed puts files in the binary: string, []byte or embed.FS."] = "//go:embed 把文件放进二进制：string、[]byte 或 embed.FS。",
  ["0..3 stops before 3. Which range operator includes the last number?"] = "0..3 在 3 之前停下。哪个范围运算符包含最后一个数？",
  ["06:40. Causeway Bay. Alex wants a muffin, a hash brown and coffee. The flat's door kiosk will not unlock until the Go file compiles."] = "06:40，铜锣湾。Alex 想要松饼、薯饼和咖啡。Go 文件编译通过之前，公寓门口的自助机不会开锁。",
  ["08:10. Breakfast done. The owner wants a delivery app before the lunch rush. First ticket: the signboard shows 銅鑼灣 wrong, because a Go string is bytes, not characters."] = "08:10。早餐吃完了。老板想在午市高峰前上线一个外卖 app。第一张工单：招牌上的 銅鑼灣 显示不对，因为 Go 的 string 是字节，不是字符。",
  ["1-7 jump straight in.   Q quest.   TAB Go/Rust.   F3 language.   F4 sound.   ESC quit."] = "1-7 直接跳入。   Q 任务。   TAB Go/Rust。   F3 语言。   F4 声音。   ESC 退出。",
  ["1..=3 is 1, 2, 3. for in Rust walks anything iterable: ranges, Vec, iterators."] = "1..=3 是 1、2、3。Rust 的 for 能遍历任何可迭代的东西：范围、Vec、迭代器。",
  ['1..=5 is RangeInclusive; 1..5 stops at 4. Also in patterns: 1..=5 => "low".'] = '1..=5 是 RangeInclusive；1..5 到 4 就停。模式里也能用：1..=5 => "low"。',
  ["13:00. CODE RUSH, the live coding show on the Times Square screen. A crowd, a buzzer, seven rounds. Answer without a miss to keep the combo. Round one: recursion, and why fib needs a memo."] = "13:00。CODE RUSH，时代广场大屏上的编程直播秀。人群、抢答器、七个回合。一题不错才能保住连击。第一回合：递归，以及 fib 为什么需要 memo。",
  ["15:00. Lunch is done at Lucky Mac. Mei's laptop shows the Times Square branch: every kiosk of Lucky Mac Express is frozen on a Rust file with no main. Alex knows Go. Mei knows Rust. They start walking."] = "15:00。Lucky Mac 的午饭吃完了。Mei 的笔记本显示时代广场分店：幸运麦 Express 的每台自助机都卡在一个没有 main 的 Rust 文件上。Alex 会 Go。Mei 会 Rust。他们动身出发。",
  ["15:08. The tram stop on Percival Street. The next-tram sign runs a tiny Rust program and it will not compile: someone tried to change a value that was never marked mut. Mei fixes it while Alex reads the error messages out loud."] = "15:08。波斯富街的电车站。下一班电车的指示牌跑着一个小 Rust 程序，却编译不过：有人想改一个从没标 mut 的值。Mei 动手修，Alex 大声念错误信息。",
  ["15:15. The underpass at Causeway Bay MTR exit A. The Lucky Mac Express ad gate should show muffin, coffee or set as people walk past, but its match has a hole and the loop never ends. Mei counts the cases on her fingers."] = "15:15。铜锣湾地铁 A 出口的地下通道。幸运麦 Express 的广告门应该在人经过时显示松饼、咖啡或套餐，可它的 match 有个漏洞，循环也停不下来。Mei 掰着手指数情况。",
  ["15:20. The footbridge over Canal Road, Times Square's clock ahead. The Express delivery board on the bridge shows the price of every set, but the pricing function returns nothing and the seat finder crashes on an empty table. Alex tries the Rust himself for the first time."] = "15:20。跨过坚拿道的天桥，前方是时代广场的大钟。桥上的 Express 外卖板显示每份套餐的价格，可定价函数什么都不返回，找座位的功能遇到空桌就崩。Alex 第一次自己动手写 Rust。",
  ["15:25. The atrium of Times Square, the crab sticker on the Express order kiosk. The kiosk prints a receipt, then tries to read the same String again and the compiler says: value used after move. Mei explains who owns the tray."] = "15:25。时代广场中庭，Express 点餐机上贴着螃蟹贴纸。点餐机打印收据，然后想再读同一个 String，编译器说：value used after move。Mei 解释托盘归谁。",
  ["15:30. The queue outside Lucky Mac Express, twelve people and a crab sticker on the board. The board should list every order's price and count the muffins per table, but the Vec is never pushed to and the HashMap panics on a missing key. Siu Ming waves them to the front."] = "15:30。幸运麦 Express 门外的队伍，十二个人，看板上一张螃蟹贴纸。看板应该列出每个订单的价格并按桌统计松饼，可 Vec 从没被 push 过，HashMap 一遇到不存在的键就 panic。小明挥手叫他们到前面来。",
  ["15:35. The counter of Lucky Mac Express at last, the crab sticker smiling on the till. The till keeps orders as loose tuples and cannot print them, and a size of Medium sneaks in that the kitchen does not know. Siu Ming needs an Order type before the afternoon set can be sold."] = "15:35。终于到了幸运麦 Express 的柜台，收银机上的螃蟹贴纸在笑。收银机用零散的元组存订单，打印不出来，还混进一个厨房不认识的 Medium 尺寸。小明需要一个 Order 类型，下午茶套餐才能卖。",
  ["16:00. Lucky Mac Express, Times Square. The till took a coin it could not parse and froze on a red Err. Siu Ming has a queue; Alex has to learn how Rust hands errors back."] = "16:00。幸运麦 Express，时代广场。收银机收了一枚解析不了的硬币，卡在红色的 Err 上。小明那边排着队；Alex 得学会 Rust 怎么把错误交回来。",
  ["16:10. The Express kitchen. Chef Bo's pass runs every station through one Rust program, but the grill and the wok speak different types and the order board shows nothing. A trait gives them one shared voice."] = "16:10。Express 的厨房。波师傅的出餐口用一个 Rust 程序管所有工位，可烤架和炒锅说的是不同的类型，订单板什么都不显示。一个 trait 给它们一个共同的声音。",
  ["16:20. The kiosk in the mall corridor has one price list in u32 and one weight list in f64, and two copies of every function. The crab on the screen sulks. Generics fold them into one."] = "16:20。商场走廊的自助机有一份 u32 的价格表和一份 f64 的重量表，每个函数都写了两遍。屏幕上的螃蟹在生气。泛型把它们合成一个。",
  ["16:30. The set table by the window. The receipt printer holds a reference to a name that was freed one line earlier and Rust refuses to build. Alex learns to say how long a borrow lives."] = "16:30。窗边的套餐桌。收据打印机持有一个名字的引用，而那个名字在前一行就被释放了，Rust 拒绝编译。Alex 学着说出一次借用能活多久。",
  ["16:40. Three orders, one cook, one thread: the pineapple buns wait while the kettle boils. Chef Bo wants the grill, the kettle and the pass to run at the same time. Rust threads are real OS threads; no go keyword here."] = "16:40。三个订单，一个厨师，一个线程：水壶烧着，菠萝包只能等。波师傅想让烤架、水壶和出餐口同时干活。Rust 的线程是真正的操作系统线程；这里没有 go 关键字。",
  ["16:50. Two tills at Lucky Mac Express and one kitchen. Orders sit in a shared Vec that both tills scribble on and the kitchen never sees. Mei replaces the Vec with a channel: many senders, one receiver."] = "16:50。幸运麦 Express 两台收银机，一个厨房。订单堆在一个共享 Vec 里，两台收银机乱写，厨房却从没看到。Mei 用 channel 换掉 Vec：多个发送者，一个接收者。",
  ["17:00. Last hour before the tea set. Both tills bump one sold counter from two threads and the total drifts. Rc will not even compile across threads; Mei reaches for Arc, Mutex and one atomic. Get it right and the afternoon tea set is yours."] = "17:00。下午茶套餐前的最后一小时。两台收银机从两个线程给同一个销量计数器加一，总数却对不上。Rc 跨线程连编译都过不了；Mei 拿出 Arc、Mutex 和一个原子类型。做对了，下午茶套餐就是你的。",
  ["17:00. Lucky Mac Express, Times Square. The receipt printer writes the shop name as 銅鑼 and a broken square. Someone sliced a String by byte count. Mei opens ticket one."] = "17:00。幸运麦 Express，时代广场。收据打印机把店名打成了 銅鑼 加一个残缺的方块。有人按字节数切了 String。Mei 打开第一张工单。",
  ["17:10. The till at Lucky Mac Express unwraps every parse. One bad keypad entry and the drawer prints a stack trace instead of a receipt. Siu Ming wants a real error type."] = "17:10。幸运麦 Express 的收银机对每个 parse 都 unwrap。键盘输错一次，钱箱打出的不是收据而是堆栈跟踪。小明想要一个真正的错误类型。",
  ["17:20. The kitchen printer at Lucky Mac Express runs a hand-written index loop. It skips the first dish and prints the last one twice. Chef Bo hands Alex ticket three: iterators."] = "17:20。幸运麦 Express 的厨房打印机跑着一个手写的下标循环。它跳过第一道菜，最后一道打两次。波师傅把第三张工单交给 Alex：迭代器。",
  ['17:30. Under the mall atrium screens, the rider app and the kitchen disagree on field names, and every order arrives as "name": null. Ticket four: teach the structs to speak JSON with serde.'] = '17:30。商场中庭大屏下，骑手 app 和厨房在字段名上吵翻了，每个订单送到都是 "name": null。第四张工单：用 serde 教 struct 说 JSON。',
  ["17:40. Russell Street. Riders idle by the tram stop while the delivery backend fetches ETAs one by one, blocking on each. Ticket five: make the calls async and run them together on tokio."] = "17:40。罗素街。骑手们在电车站旁发呆，外卖后端却在一个一个地取 ETA，每次都阻塞。第五张工单：把调用改成 async，放到 tokio 上一起跑。",
  ["17:50. The pickup queue at Lucky Mac Express is out the door and the new backend is still a folder of .rs files. Alex has go build in his fingers. Mei: in Rust it is all cargo."] = "17:50。幸运麦 Express 的取餐队伍排到了门外，新后端还只是一个装满 .rs 文件的文件夹。Alex 手指记得的是 go build。Mei：在 Rust 里全靠 cargo。",
  ["17:55. Lucky Mac Express, the set counter. The backend compiles, but Mei's review has six comments: this is 2015 Rust. Alex rewrites each one the modern way. Then it ships. SHIPPED."] = "17:55。幸运麦 Express，套餐柜台。后端编译过了，但 Mei 的审查留了六条评论：这是 2015 年的 Rust。Alex 把每一处都改成现代写法。然后上线。已上线。",
  ["19:00. CODE RUSH, the live coding show on the Times Square screen, evening edition: Rust. A crowd, a buzzer, seven rounds, Mei at the keyboard. No misses keeps the combo. Round one: recursion, and why fib needs a memo."] = "19:00。CODE RUSH，时代广场大屏上的编程直播秀，夜场：Rust。人群、抢答器、七个回合，Mei 坐在键盘前。一题不错才能保住连击。第一回合：递归，以及 fib 为什么需要 memo。",
  ["19:08. Round two, and the screen shows a tree of order numbers. Insert, walk in order, measure the height. In Rust a tree is a struct with two Option<Box<Node>> fields, and the compiler wants to know its size."] = "19:08。第二回合，屏幕上是一棵订单号组成的树。插入、中序遍历、量高度。在 Rust 里，树是一个带两个 Option<Box<Node>> 字段的 struct，而编译器想知道它有多大。",
  ["19:17. Round three puts the MTR map on the big screen: stations are nodes, lines are edges. Mei has to reach every station once. Wide first with a queue, then deep with a stack, and a HashSet so nobody loops forever."] = "19:17。第三回合把港铁线路图搬上大屏：站是节点，线是边。Mei 要把每个站都走到一次。先用队列横着走，再用栈往深里走，还要一个 HashSet，免得有人一直绕圈。",
  ["19:26. Round four is the chain: a linked list of order tickets, out on the street where the delivery riders queue. Each node owns the next one. Reverse it, walk it, find the middle, and never touch a raw pointer."] = "19:26。第四回合是这条链：一串订单票组成的链表，就在骑手排队的那条街上。每个节点拥有下一个节点。把它反转、走一遍、找到中点，而且全程不碰裸指针。",
  ["19:35. Round five, the shuffle. The screen dumps a hundred order prices in random order. Mei writes merge sort from memory, then the host wants the std spelling: stable, unstable, and a binary search on the result."] = "19:35。第五回合，洗牌。屏幕上倒出一百个乱序的订单价格。Mei 凭记忆手写归并排序，然后主持人要她给出 std 的写法：稳定的、不稳定的，还有在结果上做一次二分查找。",
  ["19:44. Round six, the classics, back on the mall floor with the crowd pressing in. Two-sum, a palindrome, an anagram, a word count. Every one of them is a hash map or an array of 26, and every one is O(n)."] = "19:44。第六回合，经典题，回到商场大堂，人群围了上来。两数之和、回文、变位词、词频。每一题不是哈希表就是长度 26 的数组，而且每一题都是 O(n)。",
  ["19:55. The final, the one they always ask: N worker threads pull jobs from one channel. The Times Square screen shows the Lucky Mac Express kitchen as the diagram. Get the lock, the drop and the join right and the prize is HIRED."] = "19:55。最后一回合，他们总要问的那道题：N 个工作线程从同一条 channel 里取任务。时代广场的大屏把幸运麦 Express 的厨房画成了示意图。锁、drop 和 join 都做对，奖品就是 HIRED。",
  ["7 streets. One language. Type the answers."] = "7 条街。一门语言。输入答案。",
  [":= declares and assigns. Type comes from the right-hand side."] = ":= 声明并赋值。类型来自右侧。",
  [":= infers the type. var names it. const never changes. int starts at 0."] = ":= 推断类型。var 写明类型。const 永不改变。int 从 0 开始。",
  ["< PREV"] = "< 上一步",
  ["<-chan T and chan<- T let the compiler stop the wrong side from sending or closing."] = "<-chan T 和 chan<- T 让编译器阻止错误的一方发送或关闭。",
  ["? calls From::from on the error. Without the impl, use .map_err(OrderError::BadQty) by hand."] = "? 会对错误调用 From::from。没有这个 impl，就得手写 .map_err(OrderError::BadQty)。",
  ["? on Option returns None when it sees None. The function type must be Option as well."] = "Option 上的 ? 遇到 None 就返回 None。函数的返回类型也必须是 Option。",
  ["? unwraps Ok, or returns Err early from the function. Only works where the return type is Result or Option."] = "? 拆开 Ok，否则从函数提前返回 Err。只在返回类型是 Result 或 Option 的地方能用。",
  ["A String has one owner. Assigning moves it. & borrows, &mut borrows exclusively. Values drop at the end of their scope."] = "一个 String 只有一个所有者。赋值就是移动。& 借用，&mut 独占借用。值在作用域结束时 drop。",
  ["A Vec is your Go slice. An array knows its length at compile time."] = "Vec 就是你的 Go slice。数组在编译期就知道自己的长度。",
  ["A bang. vec! and format! end the same way."] = "一个感叹号。vec! 和 format! 的结尾也一样。",
  ["A buffered channel blocks only when full. Unbuffered blocks on every send until someone receives."] = "有缓冲的 channel 只在满时阻塞。无缓冲的每次发送都阻塞，直到有人接收。",
  ["A buffered channel is a counting semaphore. golang.org/x/sync/semaphore is the weighted version."] = "带缓冲 channel 就是计数信号量。golang.org/x/sync/semaphore 是加权版本。",
  ["A call that can fail returns Result. Handle Err, or pass it up with ?."] = "可能失败的调用返回 Result。处理 Err，或者用 ? 往上传。",
  ["A channel that holds 3 muffins before a send blocks. Fill: make(chan string, ___)"] = "能存 3 个松饼才阻塞发送的 channel。填空：make(chan string, ___)",
  ["A closure captures n. Each call to add(2) has its own n."] = "闭包捕获 n。每次调用 add(2) 都有自己的 n。",
  ["A cold coffee came back. The app says 'error' and nothing else."] = "一杯凉咖啡被退回来了。app 只显示 'error'，别的什么也没说。",
  ["A compile-time value with an UPPER_CASE name and a required type. Which keyword?"] = "编译期的值，名字全大写，必须写类型。哪个关键字？",
  ["A constraint that allows int and every type built on int. Fill: ___int | ___float64"] = "允许 int 以及所有基于 int 的类型的约束。填空：___int | ___float64",
  ["A cook locks the rail, pulls one ticket, releases. Which Receiver method blocks until a job arrives?"] = "厨师锁住轨，取一张单，然后放开。哪个 Receiver 方法会阻塞到有任务来？",
  ["A crash you can catch in the same goroutine. Which pair: panic and ___?"] = "同一个 goroutine 里能接住的崩溃。哪一对：panic 和 ___？",
  ['A crate writes Display and Error for you from #[error("..")]. Its name?'] = '有个 crate 能从 #[error("..")] 替你写出 Display 和 Error。它叫什么？',
  ["A customer typed 1x8 sets and the till printed a page of panic. Ticket two."] = "有顾客输入了 1x8 份，收银机打出了一整页 panic。第二张工单。",
  ["A done signal that carries no data. Fill the element type: make(chan ___)"] = "不带数据的完成信号。填元素类型：make(chan ___)",
