  ["A nil map panics when you write to it. Allocate one: floors = ___(map[string]int)"] = "向 nil map 写入会 panic。分配一个：floors = ___(map[string]int)",
  ["A node points at two children of its own type. Fill the field type: Left, Right ___"] = "节点指向两个同类型的子节点。填字段类型：Left, Right ___",
  ["A pipe that carries string. Fill: ch := make(___)"] = "传送 string 的管道。填空：ch := make(___)",
  ["A pointer to Order. Fill the type of p: var p ___Order"] = "指向 Order 的指针。填入 p 的类型：var p ___Order",
