  ['let (tx, rx) = mpsc::channel();\n// Two tills, one kitchen: each till needs its own sender.\nlet tx2 = tx.___();\nthread::spawn(move || tx.send("till 1").unwrap());\nthread::spawn(move || tx2.send("till 2").unwrap());\nfor msg in rx { println!("{msg}"); }\n'] = 'let (tx, rx) = mpsc::channel();\n// 两台收银机，一个厨房：每台收银机需要自己的发送者。\nlet tx2 = tx.___();\nthread::spawn(move || tx.send("till 1").unwrap());\nthread::spawn(move || tx2.send("till 2").unwrap());\nfor msg in rx { println!("{msg}"); }\n',
  ['let (tx, rx) = mpsc::channel();\nlet tx2 = tx.clone();\nthread::spawn(move || tx2.send("bun").unwrap());\n___(tx);   // otherwise the loop below never ends\nfor msg in rx { println!("{msg}"); }\n'] = 'let (tx, rx) = mpsc::channel();\nlet tx2 = tx.clone();\nthread::spawn(move || tx2.send("bun").unwrap());\n___(tx);   // 否则下面的循环永远不结束\nfor msg in rx { println!("{msg}"); }\n',
  ["let (tx, rx) = mpsc::channel();\ntx.send(7).unwrap();\n// The kitchen waits here until an order arrives.\nlet order: u32 = rx.___().unwrap();\n"] = "let (tx, rx) = mpsc::channel();\ntx.send(7).unwrap();\n// 厨房在这里等，直到订单到来。\nlet order: u32 = rx.___().unwrap();\n",
  ["let Some(x) = opt else { return }; binds x for the rest of the function. No nesting."] = "let Some(x) = opt else { return }; 让 x 在函数剩余部分都可用。没有嵌套。",
  ["let bill = vec![18, 0, 42, 0, 25];\n// into_iter gives i32; the closure sees &i32\nlet ok: Vec<_> = bill.into_iter().___(|p| *p > 0).collect();\nassert_eq!(ok, vec![18, 42, 25]);\n"] = "let bill = vec![18, 0, 42, 0, 25];\n// into_iter 给出 i32；闭包看到的是 &i32\nlet ok: Vec<_> = bill.into_iter().___(|p| *p > 0).collect();\nassert_eq!(ok, vec![18, 42, 25]);\n",
  ["let binds. mut allows change. const needs a type. as converts. A new let can shadow an old name."] = "let 绑定。mut 允许修改。const 必须写类型。as 做转换。新的 let 可以遮蔽旧名字。",
  ['let dish = "curry rice";\nlet qty = 2;\n// like println! but it returns the String\nlet line = ___!("{qty} x {dish}");\n'] = 'let dish = "curry rice";\nlet qty = 2;\n// 像 println!，但它把 String 返回给你\nlet line = ___!("{qty} x {dish}");\n',
  ['let dishes = ["curry rice", "noodles", "toast"];\n// nothing runs before this call; turbofish names the type\nlet lens = dishes.iter().map(|d| d.len()).___::<Vec<_>>();\nassert_eq!(lens, vec![10, 7, 5]);\n'] = 'let dishes = ["curry rice", "noodles", "toast"];\n// 这一句之前什么都不会执行；turbofish 指定类型\nlet lens = dishes.iter().map(|d| d.len()).___::<Vec<_>>();\nassert_eq!(lens, vec![10, 7, 5]);\n',
  ['let dishes = ["curry rice", "noodles", "toast"];\n// yields (usize, &&str) pairs, starting from 0\nfor (i, d) in dishes.iter().___() {\n    println!("{}. {d}", i + 1);\n}\n'] = 'let dishes = ["curry rice", "noodles", "toast"];\n// 产出 (usize, &&str) 对，从 0 开始\nfor (i, d) in dishes.iter().___() {\n    println!("{}. {d}", i + 1);\n}\n',
  ['let dishes = vec!["curry rice", "noodles", "toast"];\n// borrows every element as &&str; dishes stays usable\nfor d in dishes.___() {\n    println!("ticket: {d}");\n}\n'] = 'let dishes = vec!["curry rice", "noodles", "toast"];\n// 以 &&str 借用每个元素；dishes 之后仍可用\nfor d in dishes.___() {\n    println!("ticket: {d}");\n}\n',
  ['let district = "銅鑼灣";\nlet n = district.___().count();\nassert_eq!(n, 3);\n// the receipt now cuts at whole characters\n'] = 'let district = "銅鑼灣";\nlet n = district.___().count();\nassert_eq!(n, 3);\n// 收据现在按整个字符来切\n',
  ["let else, matches!, impl Trait, ..=, ? on Option, is_some_and: less nesting, same safety."] = "let else、matches!、impl Trait、..=、Option 上的 ?、is_some_and：更少嵌套，同样安全。",
  ['let eta: Option<u32> = fetch_eta_cached(order.id);\n// Rust 1.70: None -> false, Some(e) -> the closure result\nlet fast = eta.___(|e| e < 10);\nif fast { println!("promise the customer 10 minutes"); }\n'] = 'let eta: Option<u32> = fetch_eta_cached(order.id);\n// Rust 1.70：None -> false，Some(e) -> 闭包的结果\nlet fast = eta.___(|e| e < 10);\nif fast { println!("promise the customer 10 minutes"); }\n',
  ['let menu = vec!["bun", "egg tart", "milk tea"];\n// Borrow menu from threads; all end before the block does.\nthread::___(|s| {\n    s.spawn(|| println!("{}", menu[0]));\n    s.spawn(|| println!("{}", menu[1]));\n});\n'] = 'let menu = vec!["bun", "egg tart", "milk tea"];\n// 从线程里借用 menu；全部在块结束前结束。\nthread::___(|s| {\n    s.spawn(|| println!("{}", menu[0]));\n    s.spawn(|| println!("{}", menu[1]));\n});\n',
  ["let mut count = 0; Immutable by default is Rust's first safety rule. The sign counts again."] = "let mut count = 0; 默认不可变是 Rust 的第一条安全规则。指示牌又开始计数了。",
  ['let mut counts: HashMap<&str, u32> = HashMap::new();\nfor w in "muffin coffee muffin".split(\' \') {\n    // start at 0 if w is new, then bump it either way\n    *counts.entry(w).___(0) += 1;\n}\nassert_eq!(counts["muffin"], 2);\n'] = 'let mut counts: HashMap<&str, u32> = HashMap::new();\nfor w in "muffin coffee muffin".split(\' \') {\n    // w 是新词就从 0 开始，然后一律加一\n    *counts.entry(w).___(0) += 1;\n}\nassert_eq!(counts["muffin"], 2);\n',
  ["let mut handles = Vec::new();\nfor id in 0..3 {\n    let rx = Arc::clone(&rx);\n    // a new OS thread runs the closure; move hands over rx\n    handles.push(thread::___(move || worker(id, rx)));\n}\n"] = "let mut handles = Vec::new();\nfor id in 0..3 {\n    let rx = Arc::clone(&rx);\n    // 一个新的操作系统线程跑这个闭包；move 把 rx 交过去\n    handles.push(thread::___(move || worker(id, rx)));\n}\n",
  ["let mut ids = vec![9, 2, 7, 2, 5];\n// equal ids may swap places; nobody can tell\nids.___();\nassert_eq!(ids, [2, 2, 5, 7, 9]);\n"] = "let mut ids = vec![9, 2, 7, 2, 5];\n// 相同的 id 可能换位置；没人看得出来\nids.___();\nassert_eq!(ids, [2, 2, 5, 7, 9]);\n",
  ['let mut left = 3;\n___ left > 0 {\n    left -= 1;\n    if left == 1 { continue; }   // skip this round\n    println!("{}", left);\n}\n'] = 'let mut left = 3;\n___ left > 0 {\n    left -= 1;\n    if left == 1 { continue; }   // 跳过这一轮\n    println!("{}", left);\n}\n',
  ['let mut order = String::new();\norder.___("curry rice");\norder.___(" + hash brown");\nlet loud = order.to_uppercase();\n'] = 'let mut order = String::new();\norder.___("curry rice");\norder.___(" + hash brown");\nlet loud = order.to_uppercase();\n',
  ['let mut tray = vec![7, 8];\n// pop returns an Option: a value, or None if empty.\nif let ___(id) = tray.pop() {\n    println!("serving order {id}");\n}\n'] = 'let mut tray = vec![7, 8];\n// pop 返回 Option：一个值，空了就是 None。\nif let ___(id) = tray.pop() {\n    println!("serving order {id}");\n}\n',
  ['let mut tries = 0;\nlet code = ___ {\n    tries += 1;\n    if tries == 3 { break tries * 10; }\n};\nprintln!("{}", code);   // 30\n'] = 'let mut tries = 0;\nlet code = ___ {\n    tries += 1;\n    if tries == 3 { break tries * 10; }\n};\nprintln!("{}", code);   // 30\n',
  ["let n = if a > b { a } else { b }; Both branches must have the same type. n is 22."] = "let n = if a > b { a } else { b }; 两个分支类型必须相同。n 是 22。",
  ['let order = Order { name: "toast".into(), qty: 2 };\n// takes a reference; returns Result<String, Error>\nlet text = serde_json::___(&order)?;\nassert_eq!(text, r#"{"name":"toast","qty":2}"#);\n'] = 'let order = Order { name: "toast".into(), qty: 2 };\n// 接收引用；返回 Result<String, Error>\nlet text = serde_json::___(&order)?;\nassert_eq!(text, r#"{"name":"toast","qty":2}"#);\n',
  ['let order = String::from("pineapple bun");\n// The thread may outlive this block: give it the String.\nlet h = thread::spawn(___ || {\n    println!("toasting {order}");\n});\nh.join().unwrap();\n'] = 'let order = String::from("pineapple bun");\n// 线程可能活得比这个块久：把 String 交给它。\nlet h = thread::spawn(___ || {\n    println!("toasting {order}");\n});\nh.join().unwrap();\n',
  ["let price = 28; The type is inferred as i32. Without mut it can never change."] = "let price = 28; 类型推断为 i32。没有 mut 就永远改不了。",
  ['let prices = [18, 22, 45, 60];       // already sorted\n// halve the range each step\nmatch prices.___(&45) {\n    Ok(i) => println!("found at {i}"),\n    Err(i) => println!("would insert at {i}"),\n}\n'] = 'let prices = [18, 22, 45, 60];       // 已经排好序\n// 每一步把范围对半砍\nmatch prices.___(&45) {\n    Ok(i) => println!("found at {i}"),\n    Err(i) => println!("would insert at {i}"),\n}\n',
  ["let prices = vec![18, 42, 25];\n// acc starts at 0; the closure returns the next acc\nlet total = prices.iter().___(0, |acc, p| acc + p);\nassert_eq!(total, 85);\n"] = "let prices = vec![18, 42, 25];\n// acc 从 0 开始；闭包返回下一个 acc\nlet total = prices.iter().___(0, |acc, p| acc + p);\nassert_eq!(total, 85);\n",
  ["let prices = vec![18, 42, 25];\n// the turbofish tells it which number type to add into\nlet total = prices.iter().___::<i32>();\nassert_eq!(total, 85);\n"] = "let prices = vec![18, 42, 25];\n// turbofish 告诉它要加成哪种数字类型\nlet total = prices.iter().___::<i32>();\nassert_eq!(total, 85);\n",
  ["let qty = vec![1, 2, 3];\n// a closure: the parameter sits between two pipes\nlet doubled: Vec<i32> = qty.iter().map(___ x * 2).collect();\nassert_eq!(doubled, vec![2, 4, 6]);\n"] = "let qty = vec![1, 2, 3];\n// 一个闭包：参数夹在两根竖线之间\nlet doubled: Vec<i32> = qty.iter().map(___ x * 2).collect();\nassert_eq!(doubled, vec![2, 4, 6]);\n",
  ["let sold = Arc::new(Mutex::new(0u32));\n// Each thread needs its own handle to the same counter.\nlet mine = ___(&sold);\nthread::spawn(move || { *mine.lock().unwrap() += 1; });\n"] = "let sold = Arc::new(Mutex::new(0u32));\n// 每个线程需要自己的一个指向同一计数器的句柄。\nlet mine = ___(&sold);\nthread::spawn(move || { *mine.lock().unwrap() += 1; });\n",
  ["let sold = Arc::new(Mutex::new(0u32));\n// Take the guard; it opens again when it goes out of scope.\nlet mut n = sold.___().unwrap();\n*n += 1;\n"] = "let sold = Arc::new(Mutex::new(0u32));\n// 拿到守卫；它离开作用域时会重新打开。\nlet mut n = sold.___().unwrap();\n*n += 1;\n",
  ['let text = r#"{"dish":"toast","tags":["hot","new"]}"#;\n// an enum: Null, Bool, Number, String, Array, Object\nlet v: serde_json::___ = serde_json::from_str(text)?;\nprintln!("{}", v["tags"][0]);   // "hot"\n'] = 'let text = r#"{"dish":"toast","tags":["hot","new"]}"#;\n// 一个 enum：Null, Bool, Number, String, Array, Object\nlet v: serde_json::___ = serde_json::from_str(text)?;\nprintln!("{}", v["tags"][0]);   // "hot"\n',
  ['let text = r#"{"name":"noodles","qty":1}"#;\n// the type annotation tells serde what to build\nlet order: Order = serde_json::___(text)?;\nassert_eq!(order.qty, 1);\n'] = 'let text = r#"{"name":"noodles","qty":1}"#;\n// 类型标注告诉 serde 要构造什么\nlet order: Order = serde_json::___(text)?;\nassert_eq!(order.qty, 1);\n',
  ['let typed = "18";\n// FromStr does the work; the turbofish picks the type\nlet qty = typed.___::<i32>()?;\nprintln!("{qty} sets");\n'] = 'let typed = "18";\n// FromStr 负责干活；turbofish 选定类型\nlet qty = typed.___::<i32>()?;\nprintln!("{qty} sets");\n',
  ['light := "green"\n___ light {\ncase "green":\n    walk()\n}\n'] = 'light := "green"\n___ light {\ncase "green":\n    walk()\n}\n',
  ["lo, hi := 0, len(a)         // [lo, hi)\nfor lo < hi {\n    mid := lo + (hi-lo)/___\n"] = "lo, hi := 0, len(a)         // [lo, hi)\nfor lo < hi {\n    mid := lo + (hi-lo)/___\n",
  ["lock() returns a MutexGuard; unwrap fails only if another thread panicked while holding it. The guard unlocks on drop."] = "lock() 返回 MutexGuard；只有别的线程持锁时 panic 了 unwrap 才会失败。守卫在 drop 时解锁。",
  ["log n levels, n work per level: O(n log n). The base case is a slice of 0 or 1."] = "log n 层，每层 n 的工作量：O(n log n)。base case 是长度 0 或 1 的切片。",
  ['log.Fatal(http.___(":8080", nil))   // nil = default mux\n'] = 'log.Fatal(http.___(":8080", nil))   // nil = 默认 mux\n',
  ["longest returns one of its inputs. Which lifetime does the return value carry?"] = "longest 返回它的某个输入。返回值带哪个生命周期？",
  ["loop { ... break value; } is an expression. code becomes 30. The gate stops spinning."] = "loop { ... break value; } 是表达式。code 变成 30。闸门不再空转。",
  ["low:high. Includes low, excludes high. Same backing array, no copy."] = "low:high。包含 low，不含 high。同一底层数组，不复制。",
  ["main can fail in many ways. Which pointer type wraps any dyn Error?"] = "main 有很多种失败方式。哪种指针类型能包住任何 dyn Error？",
  ["main sends on an unbuffered channel with nobody receiving. The runtime reports: all goroutines are asleep - ___!"] = "main 向无缓冲 channel 发送，却没人接收。运行时报告：all goroutines are asleep - ___!",
  ["make (or a {} literal) before the first write. Reading a nil map is safe."] = "第一次写入前先 make（或 {} 字面量）。读 nil map 是安全的。",
