  ["u for unsigned, then the word for pointer size. Same type as len() returns."] = "u 代表 unsigned，后面接表示指针大小的那个词。和 len() 返回的类型一样。",
  ["u for unsigned, then the word size. It is also the type used to index a Vec."] = "u 代表无符号，后面是机器字长。它也是给 Vec 做索引的类型。",
  ["unwrap, then an underscore, then a two-letter word."] = "unwrap，然后下划线，然后一个两字母的词。",
  ["unwrap_or(default) returns the Ok value or your default. Sibling: unwrap_or_else(|e| ...). Zero coins, but no crash."] = "unwrap_or(default) 返回 Ok 里的值或你的默认值。兄弟方法：unwrap_or_else(|e| ...)。零个硬币，但不崩。",
  ['use serde::{Deserialize, ___};\n// Cargo.toml: serde = {version="1", features=["derive"]}\n#[derive(Debug, ___, Deserialize)]\nstruct Order {\n    name: String,\n    qty: u32,\n}\n'] = 'use serde::{Deserialize, ___};\n// Cargo.toml: serde = {version="1", features=["derive"]}\n#[derive(Debug, ___, Deserialize)]\nstruct Order {\n    name: String,\n    qty: u32,\n}\n',
  ["use std::collections::HashMap;\n// station id -> the ids one hop away (an adjacency list)\ntype Graph = HashMap<u32, ___<u32>>;\nfn degree(g: &Graph, n: u32) -> usize {\n    g[&n].len()          // how many exits this station has\n}\n"] = "use std::collections::HashMap;\n// 站号 -> 一跳之外的站号（邻接表）\ntype Graph = HashMap<u32, ___<u32>>;\nfn degree(g: &Graph, n: u32) -> usize {\n    g[&n].len()          // 这个站有几个出口\n}\n",
  ['use std::collections::HashMap;\nfn main() {\n    let mut count = HashMap::new();\n    count.insert("t7", 2);\n    *count.___("t4").or_insert(0) += 1;   // t4 is 1\n    println!("{:?}", count.get("t9"));    // None\n}\n'] = 'use std::collections::HashMap;\nfn main() {\n    let mut count = HashMap::new();\n    count.insert("t7", 2);\n    *count.___("t4").or_insert(0) += 1;   // t4 是 1\n    println!("{:?}", count.get("t9"));    // None\n}\n',
  ["use std::collections::HashMap; The :: walks the path. std is always there, no Cargo.toml line needed."] = "use std::collections::HashMap; 用 :: 走路径。std 一直都在，不用在 Cargo.toml 里加行。",
  ['use std::error::Error;\nfn main() -> Result<(), ___<dyn Error>> {\n    let qty: i32 = "18".parse()?;   // ParseIntError fits\n    let text = std::fs::read_to_string("menu.txt")?;\n    println!("{qty} sets, {} bytes of menu", text.len());\n    Ok(())\n}\n'] = 'use std::error::Error;\nfn main() -> Result<(), ___<dyn Error>> {\n    let qty: i32 = "18".parse()?;   // ParseIntError 装得进去\n    let text = std::fs::read_to_string("menu.txt")?;\n    println!("{qty} sets, {} bytes of menu", text.len());\n    Ok(())\n}\n',
  ['use std::fmt;\n// Receipt carries a lifetime; fmt does not need its name.\nimpl fmt::Display for Receipt<___> {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} paid {}", self.name, self.total)\n    }\n}\n'] = 'use std::fmt;\n// Receipt 带着生命周期；fmt 不需要知道它的名字。\nimpl fmt::Display for Receipt<___> {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} paid {}", self.name, self.total)\n    }\n}\n',
  ['use std::fmt;\n// Teach println!("{}") how to print an Order.\nimpl fmt::___ for Order {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} x{}", self.bun, self.qty)\n    }\n}\n'] = 'use std::fmt;\n// 教 println!("{}") 怎么打印 Order。\nimpl fmt::___ for Order {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} x{}", self.bun, self.qty)\n    }\n}\n',
  ['use std::fmt;\nimpl fmt::___ for OrderError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "order failed")\n    }\n}\n'] = 'use std::fmt;\nimpl fmt::___ for OrderError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "order failed")\n    }\n}\n',
  ['use std::fs;\n// A missing menu file is a bug: stop with a message.\nlet menu = fs::read_to_string("menu.txt")\n    .___("menu.txt must exist");\n'] = 'use std::fs;\n// 菜单文件不存在是 bug：带消息停下。\nlet menu = fs::read_to_string("menu.txt")\n    .___("menu.txt must exist");\n',
  ["use std::num::ParseIntError;\n\n#[derive(Debug)]\n___ OrderError {\n    Empty,\n    BadQty(ParseIntError),\n}\n"] = "use std::num::ParseIntError;\n\n#[derive(Debug)]\n___ OrderError {\n    Empty,\n    BadQty(ParseIntError),\n}\n",
  ["use std::num::ParseIntError;\n// Hand any parse error straight back to the caller.\nfn cents(s: &str) -> Result<u32, ParseIntError> {\n    let n: u32 = s.parse()___;\n    Ok(n * 100)\n}\n"] = "use std::num::ParseIntError;\n// 任何解析错误都直接交回给调用方。\nfn cents(s: &str) -> Result<u32, ParseIntError> {\n    let n: u32 = s.parse()___;\n    Ok(n * 100)\n}\n",
  ["use std::sync::Arc;\n// Arc: one receiver, many owners across threads.\n// The lock: only one cook holds the rail at a time.\nlet rx = Arc::new(___::new(rx));\nlet rx2 = Arc::clone(&rx);       // one clone per cook\n"] = "use std::sync::Arc;\n// Arc：一个接收者，跨线程多个所有者。\n// 锁：同一时刻只有一个厨师握着这条轨。\nlet rx = Arc::new(___::new(rx));\nlet rx2 = Arc::clone(&rx);       // 每个厨师一份 clone\n",
  ['use std::sync::RwLock;\nlet menu = RwLock::new(vec!["bun", "egg tart"]);\n// Many may look at once; only .write() has to wait.\nlet first = menu.___().unwrap()[0];\n'] = 'use std::sync::RwLock;\nlet menu = RwLock::new(vec!["bun", "egg tart"]);\n// 很多人可以同时看；只有 .write() 需要等。\nlet first = menu.___().unwrap()[0];\n',
  ["use std::sync::atomic::{AtomicUsize, Ordering};\nstatic SERVED: AtomicUsize = AtomicUsize::new(0);\n// No lock needed: add one in a single hardware step.\nSERVED.___(1, Ordering::SeqCst);\n"] = "use std::sync::atomic::{AtomicUsize, Ordering};\nstatic SERVED: AtomicUsize = AtomicUsize::new(0);\n// 不需要锁：一个硬件步骤里加一。\nSERVED.___(1, Ordering::SeqCst);\n",
  ['use std::sync::mpsc;\n// One pipe from till to kitchen: a sender and a receiver.\nlet (tx, rx) = mpsc::___();\ntx.send("egg tart").unwrap();\n'] = 'use std::sync::mpsc;\n// 从收银机到厨房的一根管子：一个发送者和一个接收者。\nlet (tx, rx) = mpsc::___();\ntx.send("egg tart").unwrap();\n',
  ["use std::sync::mpsc;\ntype Job = Box<dyn FnOnce() + Send>;\n// one rail: many senders allowed, exactly one receiver\nlet (tx, rx) = mpsc::___::<Job>();\n"] = "use std::sync::mpsc;\ntype Job = Box<dyn FnOnce() + Send>;\n// 一条轨：允许多个发送者，只有一个接收者\nlet (tx, rx) = mpsc::___::<Job>();\n",
  ['use std::thread;\n// The grill gets its own thread; the till keeps serving.\nlet grill = thread::___(|| {\n    println!("bun is toasting");\n});\ngrill.join().unwrap();\n'] = 'use std::thread;\n// 烤架有自己的线程；收银机继续服务。\nlet grill = thread::___(|| {\n    println!("bun is toasting");\n});\ngrill.join().unwrap();\n',
  ['use std::time::Duration;\n// Steep the tea for 300 ms before pouring.\nthread::___(Duration::from_millis(300));\nprintln!("pour");\n'] = 'use std::time::Duration;\n// 倒茶前先泡 300 毫秒。\nthread::___(Duration::from_millis(300));\nprintln!("pour");\n',
  ["utf8.RuneCountInString counts code points. []rune(s) makes them indexable."] = "utf8.RuneCountInString 数的是码点。[]rune(s) 让它们可以按下标访问。",
  ["v is an any that holds a string. Take it out: s := v.(___)"] = "v 是一个装着 string 的 any。把它取出来：s := v.(___)",
  ["v, ok := m[k]. If ok is false, v is the zero value and the key was missing."] = "v, ok := m[k]。ok 为 false 时，v 是零值，键不存在。",
  ["v.(T) is a type assertion. s, ok := v.(T) never panics."] = "v.(T) 是类型断言。s, ok := v.(T) 永远不会 panic。",
  ["var count [26]int\nfor _, c := range a {\n    count[c-'a']___          // add\n}\nfor _, c := range b {\n    count[c-'a']--           // remove\n}\n"] = "var count [26]int\nfor _, c := range a {\n    count[c-'a']___          // 加\n}\nfor _, c := range b {\n    count[c-'a']--           // 减\n}\n",
  ["var err error\nif err != ___ {\n    return err\n}\n"] = "var err error\nif err != ___ {\n    return err\n}\n",
  ['var floors map[string]int      // nil: read ok, write panics\nfloors = ___(map[string]int)\nfloors["Sogo"] = 1\n'] = 'var floors map[string]int      // nil：读没问题，写会 panic\nfloors = ___(map[string]int)\nfloors["Sogo"] = 1\n',
  ['var frames ___          // length is part of the type\nframes[0] = "muffin"\n'] = 'var frames ___          // 长度是类型的一部分\nframes[0] = "muffin"\n',
  ["var memo = map[int]int{}\n\nfunc fib(n int) int {\n    if v, ok := memo[n]; ___ {\n        return v            // seen before\n    }\n"] = "var memo = map[int]int{}\n\nfunc fib(n int) int {\n    if v, ok := memo[n]; ___ {\n        return v            // 之前算过\n    }\n",
  ["var mu sync.RWMutex\nmu.___()                // readers share\nn := count\nmu.RUnlock()\n"] = "var mu sync.RWMutex\nmu.___()                // 读者共享\nn := count\nmu.RUnlock()\n",
  ["var mu sync.___\nmu.Lock()\ncount++\nmu.Unlock()\n"] = "var mu sync.___\nmu.Lock()\ncount++\nmu.Unlock()\n",
  ["var n int              // zero value\nfmt.Println(n)         // prints ___\n"] = "var n int              // 零值\nfmt.Println(n)         // 打印 ___\n",
  ["var n int with no assignment. What is n?"] = "var n int 没有赋值。n 是多少？",
  ["var name type = value. Outside a function := is a compile error."] = "var 名字 类型 = 值。在函数之外用 := 是编译错误。",
  ["var once sync.___\nfunc grill() {\n    once.Do(warm)      // warm runs one time\n}\n"] = "var once sync.___\nfunc grill() {\n    once.Do(warm)      // warm 只运行一次\n}\n",
  ["var order Order\nerr := json.___(b, &order)   // pointer!\n"] = "var order Order\nerr := json.___(b, &order)   // 指针！\n",
  ["var p *Order = nil\nvar i any = p\nfmt.Println(i == nil)   // prints ___\n"] = "var p *Order = nil\nvar i any = p\nfmt.Println(i == nil)   // 打印 ___\n",
  ['var p ___Order         // address of an Order\np = &Order{Item: "set"}\n'] = 'var p ___Order         // 一个 Order 的地址\np = &Order{Item: "set"}\n',
  ["var prev *ListNode\ncur := head\nfor cur != nil {\n    next := cur.Next      // save before we cut it\n    cur.Next = ___\n    prev, cur = cur, next\n}\n"] = "var prev *ListNode\ncur := head\nfor cur != nil {\n    next := cur.Next      // 断开前先保存\n    cur.Next = ___\n    prev, cur = cur, next\n}\n",
  ["var r ___ = '灣'        // one code point\nfmt.Println(r)          // 28771\n"] = "var r ___ = '灣'        // 一个码点\nfmt.Println(r)          // 28771\n",
  ["var re *RefundError\nif errors.___(err, &re) {      // typed match\n    pay(re.Amount)\n}\n"] = "var re *RefundError\nif errors.___(err, &re) {      // 按类型匹配\n    pay(re.Amount)\n}\n",
  ['var v any = "muffin"\ns := v.(___)              // panics if v is not one\ns2, ok := v.(string)      // safe form\n'] = 'var v any = "muffin"\ns := v.(___)              // v 不是 string 就 panic\ns2, ok := v.(string)      // 安全形式\n',
  ["var wg sync.___\nwg.Add(2)\ngo cook(&wg)\nwg.Wait()\n"] = "var wg sync.___\nwg.Add(2)\ngo cook(&wg)\nwg.Wait()\n",
  ["vec![18, 22, 25] is the literal form. Vec::new() makes an empty one. Index with [0] like Go."] = "vec![18, 22, 25] 是字面量形式。Vec::new() 建一个空的。像 Go 一样用 [0] 索引。",
  ['visited := map[string]___{}\nqueue := []string{"Causeway Bay"}\nvisited["Causeway Bay"] = true\n'] = 'visited := map[string]___{}\nqueue := []string{"Causeway Bay"}\nvisited["Causeway Bay"] = true\n',
  ["wg.Add(1) per worker, or wg.Add(3) once. Pass &wg: a WaitGroup must not be copied."] = "每个 worker wg.Add(1)，或一次 wg.Add(3)。传 &wg：WaitGroup 不能被复制。",
  ["where T: Display, reads the same as <T: Display> but stays legible with many bounds."] = "where T: Display, 和 <T: Display> 意思一样，但约束多了依然好读。",
  ["while left > 0 { } Prints 2 then 0. continue jumps to the next check, break leaves."] = "while left > 0 { } 打印 2 然后 0。continue 跳到下一次检查，break 离开。",
  ["who returns a borrow of self. Write the return type with no lifetime at all."] = "who 返回对 self 的借用。写出完全不带生命周期的返回类型。",
  ["x := 1\ndefer fmt.Println(x)    // prints ___ at the end\nx = 2\n"] = "x := 1\ndefer fmt.Println(x)    // 最后打印 ___\nx = 2\n",
  ["{} uses Display. {:?} uses Debug. {n} reads a variable by name. Three muffins, printed."] = "{} 用 Display。{:?} 用 Debug。{n} 按名字读取变量。三个松饼，打印出来了。",
  ["|x| x * 2 is a closure. It captures nothing here; map calls it for every &i32."] = "|x| x * 2 是一个闭包。这里它什么都不捕获；map 对每个 &i32 调用它一次。",
  ["~T means 'underlying type T'. | joins the choices. See constraints.Ordered."] = "~T 表示“底层类型为 T”。| 连接各个选项。参见 constraints.Ordered。",
}
